function WaitlistForm({compact=false}:{compact?:boolean}){const [email,setEmail]=useState('');const [state,setState]=useState<'idle'|'sending'|'success'|'error'>('idle');async function submit(e:React.FormEvent){e.preventDefault();setState('sending');try{const r=await fetch('/api/waitlist',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email})});if(!r.ok)throw Error();setState('success');setEmail('')}catch{setState('error')}}return <div className={compact?'form-holder compact':'form-holder'}><form onSubmit={submit} className="waitlist-form"><label className="sr-only" htmlFor={compact?'footer-email':'hero-email'}>Email address</label><input id={compact?'footer-email':'hero-email'} required type="email" placeholder="Enter your email address" value={email} onChange={e=>setEmail(e.target.value)} /><button type="submit" disabled={state==='sending'}>{state==='sending'?'Joining…':'Join the waitlist'} <ArrowUpRight size={17}/></button></form><div className="form-note">{state==='success'?'You’re on the list. See you at launch!':state==='error'?'Something went wrong. Please try again.':'No spam, just the good stuff. Launch updates only.'}</div></div>}

