function FeatureUniverse(){
 const [current,setCurrent]=useState(14),[filter,setFilter]=useState('All'),[search,setSearch]=useState(''),[zoomed,setZoomed]=useState(false);
 const categories=['All','Agents','Visual','Video','Audio','Writing','Business','Workspace','Chat','Code','Research'];
 const indexes=allToolNames.map((_,i)=>i).filter(i=>(filter==='All'||toolTypes[i]===filter)&&allToolNames[i].toLowerCase().includes(search.trim().toLowerCase()));
 const active=indexes.includes(current)?current:indexes[0]??current;
 const chooseCategory=(cat:string)=>{setFilter(cat);const next=allToolNames.findIndex((name,i)=>(cat==='All'||toolTypes[i]===cat)&&name.toLowerCase().includes(search.trim().toLowerCase()));if(next>=0)setCurrent(next)};
 return <section className="section feature-universe xcmd-section" id="feature-universe"><div className="shell">
 <div className="feature-heading"><SectionEyebrow>DESIGN 02 / THE AI COMMAND CENTER</SectionEyebrow><h2>Your universe. <span className="gradient-text">Your command.</span></h2><p>Step inside the Xnovah workspace. Explore 39 planned AI experiences through an interactive command-center preview.</p></div>
 <div className="xcmd-zoom-controls"><span>COMMAND CENTER VIEW</span><button type="button" aria-pressed={zoomed} onClick={()=>setZoomed(v=>!v)}>{zoomed?<><span aria-hidden="true">−</span> Fit to screen</>:<><span aria-hidden="true">＋</span> Zoom in</>}</button></div>
 <div className={zoomed?"xcmd-shell xcmd-zoomed":"xcmd-shell"}>
 <div className="xcmd-topbar"><div className="xcmd-brand"><span className="xcmd-brandmark">✳</span><strong>XNOVAH</strong><small>AI OS / CONCEPT</small></div><div className="xcmd-topstatus"><span className="xcmd-statusdot"/> INTERACTIVE PREVIEW <span className="xcmd-top-separator">/</span> 39 TOOLS</div></div>
 <div className="xcmd-body">
 <aside className="xcmd-sidebar" aria-label="Tool categories"><div className="xcmd-side-label">WORKSPACE</div><button type="button" className={filter==='All'?'active':''} onClick={()=>chooseCategory('All')}><Layers3 size={16}/> All tools <span>39</span></button><div className="xcmd-side-label xcmd-side-gap">EXPLORE BY CATEGORY</div>{categories.slice(1).map(cat=><button type="button" key={cat} className={filter===cat?'active':''} onClick={()=>chooseCategory(cat)}><span className="xcmd-side-icon">{cat==='Agents'?'✳':cat==='Visual'?'◈':cat==='Video'?'▶':cat==='Audio'?'♫':cat==='Writing'?'✍':cat==='Business'?'▤':cat==='Workspace'?'◇':cat==='Chat'?'☷':cat==='Code'?'⌘':'⌕'}</span>{cat}<span>{toolTypes.filter(t=>t===cat).length}</span></button>)}<div className="xcmd-side-footer">✦ MADE FOR WHAT'S NEXT</div></aside>
 <div className="xcmd-main"><div className="xcmd-mainhead"><div><span>CREATIVE WORKSPACE / TOOL EXPLORER</span><h3>{filter==='All'?'Discover your next tool':filter+' tools'}</h3></div><span className="xcmd-mainbadge">DESIGN PREVIEW</span></div>
 <label className="xcmd-search"><Search size={17}/><input type="search" value={search} onChange={e=>setSearch(e.target.value)} placeholder="Search the Xnovah universe..." aria-label="Search all 39 AI tools"/>{search&&<button type="button" onClick={()=>setSearch('')} aria-label="Clear search">×</button>}</label>
 <div className="xcmd-content"><div className="xcmd-tool-list"><div className="xcmd-listhead"><span>AVAILABLE TO EXPLORE</span><span>{indexes.length} / 39</span></div><div className="xcmd-scroll-list">{indexes.map(i=><button type="button" key={allToolNames[i]} className={active===i?'active':''} onClick={()=>setCurrent(i)} aria-pressed={active===i}><span className="xcmd-tool-icon">{toolGlyphs[i]}</span><span className="xcmd-tool-label"><strong>{allToolNames[i]}</strong><small>{toolTypes[i]}</small></span><ChevronRight size={15}/></button>)}{indexes.length===0&&<p className="xcmd-noresults">No matching tools. Try another search or category.</p>}</div></div>
 <div className="xcmd-workspace"><div className="xcmd-workspace-head"><span><span className="xcmd-statusdot"/> TOOL WORKSPACE / PREVIEW</span><span>{String(active+1).padStart(2,'0')} — 39</span></div><div className={'xcmd-stage xcmd-stage-'+toolTypes[active].toLowerCase()}><div className="xcmd-stage-grid"/><div className="xcmd-stage-orbit"/><div className="xcmd-stage-core">{toolGlyphs[active]}</div><div className="xcmd-stage-float xcmd-float-a">✦ CREATIVE INTELLIGENCE</div><div className="xcmd-stage-float xcmd-float-b">{toolTypes[active].toUpperCase()} / XNOVAH</div></div><div className="xcmd-workspace-detail"><span className="xcmd-detail-tag">{toolTypes[active]} / FEATURE {String(active+1).padStart(2,'0')}</span><h4>{allToolNames[active]}</h4><p>{toolDescriptions[active]}</p><a href="#waitlist">Join the waitlist <ArrowUpRight size={16}/></a></div></div></div>
 </div>
 <aside className="xcmd-insights"><div className="xcmd-insights-heading"><Sparkles size={17}/><span>XNOVAH INTELLIGENCE</span><span className="xcmd-concept">CONCEPT</span></div><div className="xcmd-insights-body"><span className="xcmd-ai-orb">✳</span><h4>Meet your creative co-pilot.</h4><p>Explore the possibilities. Pick a tool and imagine what you could build with an AI-powered workspace.</p><div className="xcmd-prompt"><span>SELECTED EXPERIENCE</span><strong>{allToolNames[active]}</strong><small>{toolTypes[active]} · Planned capability</small></div><div className="xcmd-suggestions"><span>QUICK DISCOVERY</span>{[14,25,0,18].filter(i=>i!==active).slice(0,3).map(i=><button type="button" key={i} onClick={()=>{setFilter('All');setSearch('');setCurrent(i)}}><ArrowUpRight size={13}/>{allToolNames[i]}</button>)}</div></div><div className="xcmd-insights-foot"><span className="xcmd-statusdot"/> CONCEPT INTERFACE — NOT A LIVE CHAT</div></aside>
 </div><div className="xcmd-bottom"><span>✳ XNOVAH AI / THE CREATIVE OPERATING SYSTEM</span><span>DESIGN 02 · COMMAND CENTER</span></div></div>
 <p className="feature-disclaimer">Interactive product-design concept only. The 39 tools and co-pilot panel represent planned capabilities, not functioning AI services.</p>
 </div></section>
}
